const body = $('Webhook').first().json.body || {};

const subject = body.subject || body.mon_hoc || "Toán học";
const topic = body.topic || body.chu_de || "Tổng hợp kiến thức";
const knowledgeTested = body.knowledge_tested || body.kien_thuc || "Kiến thức trọng tâm chương trình";
const difficulty = body.difficulty || body.muc_do || "Trung bình";
const mcqCount = parseInt(body.mcq_count || body.so_cau_trac_nghiem, 10) || 5;
const essayCount = parseInt(body.essay_count || body.so_cau_tu_luan, 10) || 2;
const mcqScoreTotal = parseFloat(body.mcq_score_total || body.mcq_barem || body.diem_trac_nghiem) || 5.0;
const essayScoreTotal = parseFloat(body.essay_score_total || body.essay_barem || body.diem_tu_luan) || 5.0;
const grade = body.grade || body.khoi_lop || "Lớp 3";
const timeLimit = body.time_limit || body.thoi_gian || "40 phút";
const additionalInstructions = body.additional_instructions || body.yeu_cau_them || body.user_request || body.prompt || "Không có yêu cầu bổ sung.";

const prompt = `YÊU CẦU THIẾT KẾ ĐỀ THI TỪ GIÁO VIÊN/MENTOR:
- Môn học: ${subject}
- Khối lớp: ${grade}
- Chủ đề: ${topic}
- Kiến thức cần kiểm tra: ${knowledgeTested}
- Mức độ khó: ${difficulty}
- Thời gian làm bài: ${timeLimit}

CẤU TRÚC ĐỀ VÀ THANG ĐIỂM (BAREM):
1. Phần Trắc nghiệm (Multiple Choice):
   - Số lượng câu hỏi: ${mcqCount} câu
   - Tổng điểm phần trắc nghiệm: ${mcqScoreTotal} điểm
   - Điểm mỗi câu trắc nghiệm: ${(mcqScoreTotal / mcqCount).toFixed(2)} điểm

2. Phần Tự luận (Essay):
   - Số lượng câu hỏi: ${essayCount} câu
   - Tổng điểm phần tự luận: ${essayScoreTotal} điểm
   - Thang điểm chi tiết (Barem) cho từng câu tự luận cần được phân chia rõ ràng để đạt tổng cộng ${essayScoreTotal} điểm.

YÊU CẦU BỔ SUNG TỪ GIÁO VIÊN/MENTOR:
${additionalInstructions}

Hãy khởi tạo mã đề thi (test_id), thiết kế ĐỀ THI (de_thi) và BAREM CHẤM ĐIỂM CHI TIẾT (barem_cham_diem) dưới định dạng JSON chính xác theo đúng hướng dẫn hệ thống.`;

const systemInstruction = `[SYSTEM INSTRUCTION - TEST GENERATOR AGENT]
Bạn là Trợ lý Thiết kế Đề thi Sư phạm chuyên nghiệp. Nhiệm vụ của bạn là soạn thảo đề thi và barem chấm điểm chi tiết dưới dạng JSON chính xác 100%, KHÔNG chứa văn bản giải thích ngoài JSON.

BẮT BUỘC trả về đúng cấu trúc JSON sau (KHÔNG kèm văn bản ngoài JSON):
{
  "action": "generate",
  "test_id": "TEST_MATH3_TIMESTAMP_OR_RANDOM",
  "de_thi": {
    "title": "Tên đề thi",
    "subject": "Tên môn học",
    "grade": "Khối lớp",
    "time_limit": "Thời gian làm bài",
    "difficulty": "Mức độ khó",
    "total_score": 10.0,
    "instructions": "Hướng dẫn làm bài",
    "parts": [
      {
        "part_id": "PART_1",
        "part_name": "Phần I: Trắc nghiệm khách quan",
        "questions": [
          {
            "question_id": "MCQ_1",
            "question_number": 1,
            "prompt": "Nội dung câu hỏi trắc nghiệm...",
            "options": {
              "A": "Đáp án A",
              "B": "Đáp án B",
              "C": "Đáp án C",
              "D": "Đáp án D"
            },
            "score": 1.0
          }
        ]
      },
      {
        "part_id": "PART_2",
        "part_name": "Phần II: Tự luận",
        "questions": [
          {
            "question_id": "ESSAY_1",
            "question_number": 1,
            "prompt": "Nội dung câu hỏi tự luận...",
            "score": 2.5
          }
        ]
      }
    ]
  },
  "barem_cham_diem": {
    "test_id": "TEST_MATH3_TIMESTAMP_OR_RANDOM",
    "total_score": 10.0,
    "mcq_answers": [
      {
        "question_id": "MCQ_1",
        "correct_option": "A",
        "score": 1.0,
        "explanation": "Giải thích tại sao A đúng..."
      }
    ],
    "essay_answers": [
      {
        "question_id": "ESSAY_1",
        "score": 2.5,
        "solution_steps": [
          {
            "step": 1,
            "description": "Nội dung bước 1",
            "score": 1.0
          },
          {
            "step": 2,
            "description": "Nội dung bước 2",
            "score": 1.5
          }
        ]
      }
    ]
  }
}`;

return {
  action: "generate",
  prompt: prompt,
  system_instruction: systemInstruction
};

const llmResult = $('Test Generator Agent').first().json || {};
const rawText = llmResult.text || "";
let cleanedText = rawText.replace(/```json/gi, "").replace(/```/gi, "").trim();
let outputObj = null;

try {
  outputObj = JSON.parse(cleanedText);
} catch (e) {
  const jsonMatch = cleanedText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      outputObj = JSON.parse(jsonMatch[0]);
    } catch (e2) {
      outputObj = null;
    }
  }
}

if (outputObj && typeof outputObj === "object") {
  outputObj.action = "generate";
  return outputObj;
} else {
  return {
    action: "generate",
    status: "warning",
    message: "Test Generator Agent output could not be parsed as valid JSON.",
    raw_text: rawText
  };
}

const body = $('Webhook').first().json.body || {};

const testId = body.test_id || body.id_de_thi || "TEST_UNKNOWN";
const studentId = body.student_id || body.ten_hoc_sinh || "Học sinh";
const studentSubmission = body.student_submission || body.bai_lam || {};
const baremInfo = body.barem || body.barem_cham_diem || body.de_thi || body.de_thi_and_barem || "Dựa trên đáp án và thang điểm tiêu chuẩn cho đề thi.";

const prompt = `YÊU CẦU CHẤM BÀI THI TỪ BAREM & PHÂN TÍCH CHỦ ĐỀ YẾU:
- Mã đề thi (test_id): ${testId}
- Mã/Tên học sinh: ${studentId}

THÔNG TIN BAREM / ĐỀ THI:
${typeof baremInfo === 'object' ? JSON.stringify(baremInfo, null, 2) : baremInfo}

BÀI LÀM CỦA HỌC SINH:
${typeof studentSubmission === 'object' ? JSON.stringify(studentSubmission, null, 2) : studentSubmission}

Hãy chấm điểm bài làm của học sinh dựa trên Barem điểm được cung cấp. Đánh giá chính xác phần trắc nghiệm và chấm điểm chi tiết từng bước cho phần tự luận. ĐẶC BIỆT: Nêu rõ chủ đề chính của đề thi (topic) và tổng hợp các câu làm sai/bị trừ điểm để phân tích rõ các chủ đề/dạng bài học sinh đang bị yếu (weak_topics). Trả về kết quả chấm điểm dưới định dạng JSON theo đúng hướng dẫn hệ thống.`;

const systemInstruction = `[SYSTEM INSTRUCTION - SUBMISSION GRADER AGENT]
Bạn là Chuyên gia Chấm điểm & Phân tích Chẩn đoán Sư phạm. Nhiệm vụ của bạn là chấm bài làm của học sinh dựa trên đề thi và barem điểm được cung cấp, xác định rõ chủ đề chính của bài kiểm tra (topic), phân tích các lỗi sai để xác định những chủ đề/dạng bài học sinh đang bị yếu hoặc sai nhiều, sau đó trả về kết quả dưới dạng JSON chính xác 100%.

Quy tắc chấm điểm & Phân tích chẩn đoán:
1. Xác định chủ đề chính (topic): Trích xuất hoặc tổng hợp tên chủ đề kiến thức tổng quát của bài kiểm tra và đưa vào trường "topic" ở cấp cao nhất trong "grading_result".
2. Phần Trắc nghiệm (MCQ): So sánh đáp án học sinh chọn với correct_option trong barem. Nếu đúng nhận full điểm câu đó, sai nhận 0 điểm.
3. Phần Tự luận (Essay): Đánh giá bài giải của học sinh theo từng bước (solution_steps) trong barem. Mỗi bước làm đúng sẽ nhận số điểm của bước đó (step.score). Cho nhận xét ngắn gọn và sư phạm.
4. Tính tổng điểm thu được (total_score), tổng điểm tối đa (max_score), và tỷ lệ phần trăm (percentage).
5. PHÂN TÍCH CHỦ ĐỀ YẾU (weak_topics): Tổng hợp tất cả các câu trắc nghiệm và tự luận học sinh làm sai hoặc bị trừ điểm. Nhóm lại thành danh sách các chủ đề/mảng kiến thức học sinh đang bị yếu, gắn trường "topic" (và "topic_name"), đánh giá mức độ nghiêm trọng (Cao | Trung bình | Nhẹ), mô tả nguyên nhân lỗi sai và đưa ra lời khuyên khắc phục cụ thể.
6. Đưa ra nhận xét chung tổng quát (overall_feedback) khích lệ và chỉ ra điểm cần cải thiện.

BẮT BUỘC trả về đúng cấu trúc JSON sau (KHÔNG kèm văn bản ngoài JSON):
{
  "action": "grade",
  "test_id": "Mã đề thi",
  "student_id": "Mã/Tên học sinh",
  "grading_result": {
    "topic": "Tên chủ đề chính của đề thi/bài kiểm tra",
    "total_score": 5.0,
    "max_score": 10.0,
    "percentage": 50.0,
    "overall_feedback": "Nhận xét tổng quan sư phạm cho học sinh/phụ huynh",
    "weak_topics": [
      {
        "topic": "Tên chủ đề/dạng bài bị yếu (ví dụ: Phép cộng/trừ số có 5 chữ số có nhớ)",
        "topic_name": "Tên chủ đề/dạng bài bị yếu",
        "severity": "Cao",
        "description": "Phân tích cụ thể nguyên nhân hoặc điểm học sinh còn nhầm lẫn",
        "recommendation": "Gợi ý cách khắc phục hoặc bài tập luyện tập bổ sung"
      }
    ],
    "mcq_results": [
      {
        "question_id": "MCQ_1",
        "student_answer": "A",
        "correct_answer": "A",
        "is_correct": true,
        "score_earned": 1.0,
        "max_score": 1.0,
        "feedback": "Chính xác."
      }
    ],
    "essay_results": [
      {
        "question_id": "ESSAY_1",
        "student_answer": "Lời giải của học sinh...",
        "score_earned": 1.5,
        "max_score": 2.5,
        "step_evaluations": [
          {
            "step": 1,
            "description": "Bước 1: Tính...",
            "max_score": 1.0,
            "earned_score": 1.0,
            "comment": "Chính xác"
          },
          {
            "step": 2,
            "description": "Bước 2: Tính...",
            "max_score": 1.5,
            "earned_score": 0.5,
            "comment": "Tính toán chưa chính xác ở kết quả cuối"
          }
        ],
        "feedback": "Học sinh hiểu cách làm nhưng nhầm lẫn kết quả tính toán."
      }
    ]
  }
}`;

return {
  action: "grade",
  prompt: prompt,
  system_instruction: systemInstruction
};

